svg.script:
(function () {
  const DURATION = 12000;
  const easeInOut = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  const easeOut = t => 1 - Math.pow(1 - t, 3);
  const clamp01 = v => Math.max(0, Math.min(1, v));
  const lerp = (a, b, t) => a + (b - a) * t;

  // Live Stacking DAO APY sequence synchronized with -135 -> -45 -> +45 -> +135 -> -135
  // Starts moving quickly at 500ms; header stays visible at frame 0; all texts reveal within <= 460ms
  const SEGMENTS = [
    [0,     1700, -135, -135, 2.45, 2.45, 0],
    [1700,  2800, -135,  -45, 2.45, 5.98, 1],
    [2800,  4900,  -45,  -45, 5.98, 5.98, 1],
    [4900,  6000,  -45,   45, 5.98, 5.99, 2],
    [6000,  8100,   45,   45, 5.99, 5.99, 2],
    [8100,  9200,   45,  135, 5.99, 6.64, 3],
    [9200, 10800,  135,  135, 6.64, 6.64, 3],
    [10800,12000,  135, -135, 6.64, 2.45, 0]
  ];

  const MODES = [
    { name: 'stBTC',    desc: 'Auto-compounding sBTC yield · Liquid in DeFi' },
    { name: 'stSTXbtc', desc: 'Liquid STX staking · Direct BTC rewards' },
    { name: 'stSTX',    desc: 'Liquid STX stacking · Auto-compounding STX' },
    { name: 'Native',   desc: 'Direct BTC rewards · Non-custodial STX' }
  ];

  const txLogo = document.getElementById('tx-logo');
  const txHead = document.getElementById('tx-head');
  const txSub = document.getElementById('tx-sub');
  const txStat = document.getElementById('tx-stat');
  const txDetents = document.getElementById('tx-detents');
  const knobTurn = document.getElementById('dial-knob-turn');
  const dialArc = document.getElementById('dial-arc');
  const dialApy = document.getElementById('dial-apy');
  const modeName = document.getElementById('dial-mode-name');
  const modeDesc = document.getElementById('dial-mode-desc');
  const dLabels = [0, 1, 2, 3].map(i => document.getElementById('dl-' + i));

  function fadeWindow(t, inStart, inDur, outStart, outDur) {
    if (t < inStart) return 0;
    if (t < inStart + inDur) return easeOut((t - inStart) / inDur);
    if (t <= outStart) return 1;
    if (t < outStart + outDur) return 1 - easeInOut((t - outStart) / outDur);
    return 0;
  }

  function updateAt(rawMs) {
    const t = ((rawMs % DURATION) + DURATION) % DURATION;

    // Header visible on frame 0; all other texts fade in within <= 460ms
    if (txHead) txHead.setAttribute('opacity', fadeWindow(t, 0, 260, 11500, 480).toFixed(3));
    if (txSub)  txSub.setAttribute('opacity', fadeWindow(t, 90, 280, 11460, 480).toFixed(3));
    if (txStat) txStat.setAttribute('opacity', fadeWindow(t, 160, 280, 11420, 480).toFixed(3));
    if (txDetents) txDetents.setAttribute('opacity', fadeWindow(t, 120, 300, 11460, 480).toFixed(3));

    let seg = SEGMENTS[0];
    for (let i = 0; i < SEGMENTS.length; i++) {
      if (t >= SEGMENTS[i][0] && t <= SEGMENTS[i][1]) { seg = SEGMENTS[i]; break; }
    }
    const span = Math.max(1, seg[1] - seg[0]);
    const p = easeInOut(clamp01((t - seg[0]) / span));
    const deg = lerp(seg[2], seg[3], p);
    const frac = (deg + 135) / 270;
    const arcDash = Math.max(1.4, frac * 100);
    const apy = lerp(seg[4], seg[5], p);

    if (knobTurn) knobTurn.setAttribute('transform', 'translate(0, -2) rotate(' + deg.toFixed(2) + ')');
    if (dialArc) dialArc.setAttribute('stroke-dasharray', arcDash.toFixed(2) + ' 100');
    if (dialApy) dialApy.textContent = apy.toFixed(2);

    const activeIdx = Math.min(3, Math.max(0, Math.round(frac * 3)));
    if (modeName) modeName.textContent = MODES[activeIdx].name;
    if (modeDesc) modeDesc.textContent = MODES[activeIdx].desc;

    for (let i = 0; i < dLabels.length; i++) {
      const el = dLabels[i];
      if (!el) continue;
      if (i === activeIdx) {
        el.setAttribute('fill', '#6FF26F');
        el.removeAttribute('fill-opacity');
        el.setAttribute('class', 'detent-active');
      } else {
        el.setAttribute('fill', '#f5f5ef');
        el.setAttribute('fill-opacity', '0.34');
        el.removeAttribute('class');
      }
    }
  }

  let manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    updateAt(tMs);
  };

  const start = performance.now();
  function loop(now) {
    if (manual) return;
    updateAt(now - start);
    requestAnimationFrame(loop);
  }
  updateAt(0);
  requestAnimationFrame(loop);
})();
